{
  "items": [
    {
      "name": "Finsupp.sum_add",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_8} {N : Type u_10} [inst : Zero M] [inst_1 : AddCommMonoid N] {f : α →₀ M}\n  {h₁ h₂ : α → M → N}, (f.sum fun a b => h₁ a b + h₂ a b) = f.sum h₁ + f.sum h₂"
    },
    {
      "name": "Finsupp.sum_toMultiset",
      "module_name": "Mathlib.Data.Finsupp.Multiset",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : AddCommMonoid α] (f : α →₀ ℕ), (Finsupp.toMultiset f).sum = f.sum fun a n => n • a"
    },
    {
      "name": "Finsupp.instAdd",
      "module_name": "Mathlib.Algebra.Group.Finsupp",
      "kind": "instance",
      "type": "{ι : Type u_1} → {M : Type u_3} → [inst : AddZeroClass M] → Add (ι →₀ M)"
    },
    {
      "name": "Finsupp.sum_add_index",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_8} {N : Type u_10} [inst : DecidableEq α] [inst_1 : AddZeroClass M]\n  [inst_2 : AddCommMonoid N] {f g : α →₀ M} {h : α → M → N},\n  (∀ a ∈ f.support ∪ g.support, h a 0 = 0) →\n    (∀ a ∈ f.support ∪ g.support, ∀ (b₁ b₂ : M), h a (b₁ + b₂) = h a b₁ + h a b₂) → (f + g).sum h = f.sum h + g.sum h"
    },
    {
      "name": "DFinsupp.mk_add",
      "module_name": "Mathlib.Data.DFinsupp.Defs",
      "kind": "theorem",
      "type": "∀ {ι : Type u} {β : ι → Type v} [inst : DecidableEq ι] [inst_1 : (i : ι) → AddZeroClass (β i)] {s : Finset ι}\n  {x y : (i : ↑↑s) → β ↑i}, DFinsupp.mk s (x + y) = DFinsupp.mk s x + DFinsupp.mk s y"
    }
  ]
}
